                payload: None,
                result: None,
                created_at: now.clone(),
                updated_at: now,
                deadline: None,
            })
            .await
            .unwrap();

        let router = Router::new()
            .route("/api/v1/tasks", axum::routing::get(super::list_tasks))
            .with_state(state);

        let req = Request::builder()
            .method(Method::GET)
            .uri("/api/v1/tasks?limit=-1")
